  // Основные действия с группой: урон, лечение, стабилизация, общий запас и награды.
  "campaign.dmCatalog.apply_damage.label": "Нанести урон",
  "campaign.dmCatalog.apply_damage.summary": "Наносит общий объём урона персонажу, противнику, питомцу или нескольким существам с указанным распределением. Временные хиты поглощают урон первыми; сопротивления и спасброски от смерти учитываются автоматически.",
