  "campaign.dmCatalog.apply_damage.field.enemyId.help": "Во время боя. Ведущий-ИИ может нанести противнику урон только опасностью или воздействием окружающей среды.",
  "campaign.dmCatalog.apply_damage.field.petName.label": "Питомец",
