  "campaign.dmCatalog.apply_damage.field.targets.help": "Распределите общий урон между несколькими существами: полный, половинный, двойной или нулевой. Сопротивления учитываются после распределения.",
  "campaign.dmCatalog.apply_damage.field.amount.label": "Урон",
