  "campaign.dmCatalog.grant_item.field.srdName.help": "Если предмет назван на языке кампании, укажите соответствующий предмет из SRD или набора контента по его английскому названию. Так предмет получит правильные свойства. Для магического оружия или брони укажите и магическое название, и базовый предмет, как в SRD: Flame Tongue Scimitar или Vicious Rapier.",
  "campaign.dmCatalog.grant_item.field.tags.help": "Перечислите через запятую теги из этого списка: consumable, kept, durable, potion, healing_potion, scroll, food, water, everburning_light, bullseye_lantern, lantern, torch, candle, lamp_oil, lamp, cold_weather_gear, heavy_clothing, component_pouch, arcane_focus, holy_symbol, druidic_focus, instrument, tools, wand, staff, rod, arrows, bolts, bullets, needles, silvered, adamantine, gem, art_object, trade_good, carried. Для предмета, которого нет в SRD или наборе контента, укажите все его свойства; для уже описанного предмета — только дополнительные (например, silvered для посеребрённого длинного меча).",
