  "campaign.sound.blurb.forge": "Меха, удары молота по наковальне и недовольный звон металла.",
  "campaign.sound.blurb.graveyard": "Ветер, вороны и мокрая трава между надгробиями.",
  "campaign.sound.blurb.arcane": "Гул без видимого источника и воздух, будто уже кем-то использованный.",
  "campaign.sound.blurb.wind": "Просто ветер, не выдающий, где именно вы находитесь.",
  "campaign.sound.blurb.rain": "Ровный дождь стучит по тому, что находится над головой.",
  "campaign.sound.blurb.storm": "Ветер, дождь и гром сменяют друг друга.",
  "campaign.sound.blurb.night": "Сверчки, сова и мир, погрузившийся во тьму.",
  "campaign.sound.blurb.calm": "Пока ничего не случилось. Можно отдохнуть, закупиться и всё обсудить.",
  "campaign.sound.blurb.wonder": "Они только что увидели нечто, ради чего стоило отправиться в путь.",
  "campaign.sound.blurb.mystery": "Что-то не сходится, и они это заметили.",
  "campaign.sound.blurb.tension": "Пока всё ещё спокойно, но скоро это изменится.",
  "campaign.sound.blurb.dread": "Та самая сцена, в которой следовало бежать.",
  "campaign.sound.blurb.battle": "Бой, ради которого стоит бросать инициативу.",
  "campaign.sound.blurb.boss": "Битва, к которой кампания вела с самого начала.",
  "campaign.sound.blurb.chase": "Кто-то убегает, а кто-то стремительно его настигает.",
  "campaign.sound.blurb.triumph": "Они победили, и об этом должны узнать все.",
  "campaign.sound.blurb.sorrow": "Смерть, предательство или расплата за прошлое.",
  "campaign.sound.blurb.travel": "Мили пути остаются позади, пока ничто не нарушает дорогу.",
  "campaign.sound.blurb.festive": "Пир, ярмарка, свадьба или коронация.",
  "campaign.sound.blurb.thunder": "Так близко, что раскат ощущается всем телом.",
  "campaign.sound.blurb.door_slam": "Путь наружу только что перестал быть выходом.",
  "campaign.sound.blurb.door_creak": "Медленно — и без чьей-либо руки.",
  "campaign.sound.blurb.roar": "Что-то огромное заявляет о своём присутствии.",
  "campaign.sound.blurb.wolf_howl": "Один вой — и три ответа с разных сторон.",
  "campaign.sound.blurb.horn": "Кто-то зовёт на помощь или призывает к битве.",
  "campaign.sound.blurb.bell": "Один удар колокола — и все замолкают.",
  "campaign.sound.blurb.gong": "Для появления тех, кого никто не ждал.",
  "campaign.sound.blurb.scream": "Крик доносится оттуда, где они ещё не бывали.",
  "campaign.sound.blurb.sword_clash": "Момент, когда разговор превратился в драку.",
  "campaign.sound.blurb.magic_cast": "Что бы это ни было, оно сработало.",
  "campaign.sound.blurb.coin": "Плата, взятка или кошель, брошенный на стол.",
  "campaign.sound.blurb.crow": "Все птицы разом взлетают — а это редко сулит что-то хорошее.",
  "campaign.sound.blurb.heartbeat": "Для паузы перед спасброском от смерти.",
  "campaign.sound.blurb.chain": "Кого-то освобождают от цепей — или заковывают снова.",
  "campaign.sound.blurb.splash": "Кто-то или что-то упало в воду.",
  "campaign.sound.blurb.hit_melee": "Удар оружия достигает цели.",
  "campaign.sound.blurb.hit_ranged": "Выстрел попадает в цель.",
  "campaign.sound.blurb.hit_crit": "Удар, который меняет ход боя.",
  "campaign.sound.blurb.swing_miss": "Только свист воздуха — и ничего больше.",
  "campaign.sound.blurb.spell_fire": "Вспышка и рёв пламени.",
  "campaign.sound.blurb.spell_cold": "Иней потрескивает, сковывая всё вокруг.",
  "campaign.sound.blurb.spell_thunder": "Грохот, от которого сводит зубы.",
  "campaign.sound.blurb.spell_radiant": "Свет озвучивает чистый аккорд.",
  "campaign.sound.blurb.spell_dark": "Из кого-то вытягивают нечто холодное.",
  "campaign.sound.blurb.heal": "Возвращается тепло.",
  "campaign.sound.blurb.death": "Глухой и окончательный звук.",
  "campaign.sound.blurb.door_locked": "Ручка, которая не поддаётся.",
  "campaign.sound.blurb.door_secret": "Камень скрежещет там, где двери прежде не было.",
  "campaign.sound.blurb.thud": "Что-то тяжёлое ударяется о землю.",
