  "campaign.session.eventLog.confirm.undoTitle": "Всё равно отменить?",
  "campaign.session.eventLog.confirm.revertDescription": "Это вернёт листы персонажей, игровое время и бой к состоянию до хода: хиты, состояния, прибывших и павших существ, жетоны, области на карте, эффекты и очерёдность хода. Бой, начатый в этом ходу, завершится; подготовленные события боя снова будут готовы, принудительные результаты проверок вернутся, а разыгранная карточка снова будет ждать разрешения. Мировые события и ушедшие спутники останутся; перемотка главы отменит и их.",
