  "campaign.session.hand.tutorial.title.card": "Разыграйте карту",
  "campaign.session.hand.tutorial.body.card": "Выберите карту, затем укажите цель. Заклинания, предметы и обычные действия сгруппированы по карточкам: откройте нужную группу, чтобы выбрать вариант. Цветной угол карты показывает, какой ресурс расходуется. Потраченные карты тускнеют и объясняют причину при нажатии.",
