  "campaign.session.coordination.description.ordered": "Ведущий задал порядок действий: каждый шаг начинается после предыдущего, а персонажи внутри одного шага действуют одновременно. Опишите, что делает ваш персонаж на своём шаге. Ничего не произойдёт, пока все игроки не будут готовы. Затем ведущий разыграет весь план как одну сцену, шаг за шагом.",
