  "campaign.session.party.handToGm.description": "В библиотеке {name} записан как союзник под управлением ведущего, но здесь находится в роли персонажа игрока, поэтому ведущий не совершает за него ходы.",
  "campaign.session.party.handToGm.block.off.reason": "Спутники под управлением ИИ отключены на этом столе, поэтому добавить спутника в группу нельзя.",
  "campaign.session.party.handToGm.block.guests.reason": "На этом столе разрешены только временные гости под управлением ИИ, но не постоянные спутники группы.",
  "campaign.session.party.handToGm.block.autoGuests.reason": "В автоматическом режиме за столом с несколькими игроками, которым управляет ИИ, разрешены только временные гости. Спутник, который путешествует вместе с группой, считается постоянным.",
