  "campaign.gameSettings.world.tableLanguage": "Язык игры",
  "campaign.gameSettings.world.languageHelp": "Ведущий будет писать историю на этом языке, а сервер будет анализировать её и сообщения игроков. Интерфейс приложения, правила и книга правил останутся на английском. Для любого языка, кроме английского, серверу нужна мультиязычная модель эмбеддингов (EMBEDDING_MODEL в README).",
  "campaign.gameSettings.world.length": "Длительность кампании",
  "campaign.gameSettings.world.lengthHint": "Насколько далеко ведущий планирует историю: акты, главные противники и побочные задания. Изменение посреди кампании вступит в силу при планировании следующей саги. Если пройти финал, после любой длительности можно начать продолжение.",
