  "campaign.gameSettings.genre.blurb.dark_fantasy": "Мрачные земли, где надежды мало, а победы требуют жертв.",
  "campaign.gameSettings.genre.blurb.mystery": "Улики, подозреваемые и тайны за каждой дверью.",
