  "campaign.gameSettings.character.wealthOption.equipment": "Старт: классовое снаряжение и монеты",
  "campaign.gameSettings.character.wealthOption.rolled": "Старт: случайное золото на покупку снаряжения",
  "campaign.gameSettings.character.statsHint": "Для характеристик, определяемых броском 4d6: может ли игрок перебросить шесть костей и при каких условиях. В любом случае кости бросает сервер. При использовании правила сервера здесь учитываются результаты из библиотеки персонажа. При собственном правиле стола для каждого игрока сохраняется отдельный набор характеристик. Созданный за этим столом персонаж, как и остальные, попадёт в библиотеку игрока; персонажи из библиотеки сохраняют исходные характеристики.",
